/// <reference types="google.maps" />
/**
 * @typedef {object} MapConstructor
 */
export interface MapConstructor {
    new (mapDiv: Element, opts?: google.maps.MapOptions): google.maps.Map;
    readonly prototype: google.maps.Map;
}
/**
 * @typedef {object} MapLatLngConstructor
 */
export interface MapLatLngConstructor {
    new (latOrLatLngLiteral: number | google.maps.LatLngLiteral, lngOrNoWrap?: number | boolean | null, noWrap?: boolean): google.maps.LatLng;
    readonly prototype: google.maps.LatLng;
}
/**
 * @typedef {object} MapGeocoderConstructor
 */
export interface MapGeocoderConstructor {
    new (): google.maps.Geocoder;
    readonly prototype: google.maps.Geocoder;
}
/**
 * @typedef {object} MapMarkerConstructor
 */
export interface MapMarkerConstructor {
    new (opts?: google.maps.MarkerOptions | null): google.maps.Marker;
    readonly prototype: google.maps.Marker;
}
/**
 * @typedef {object} MapSizeConstructor
 */
export interface MapSizeConstructor {
    new (width: number, height: number, widthUnit?: string, heightUnit?: string): google.maps.Size;
    readonly prototype: google.maps.Size;
}
/**
 * @typedef {object} MapPointConstructor
 */
export interface MapPointConstructor {
    new (x: number, y: number): google.maps.Point;
    readonly prototype: google.maps.Point;
}
/**
 * @typedef {object} Gmap
 * @property {Function} Map Map.
 * @property {Function} LatLng LatLng.
 * @property {Function} Geocoder Geocoder.
 * @property {Function} Marker Marker.
 * @property {Function} Size Size.
 * @property {Function} Point Point.
 * @property {object} GeocoderStatus Geocoder status.
 * @property {object} MapTypeId Map type ID.
 * @property {object} event Event.
 * @property {Function} event.clearInstanceListeners Clear instance listeners.
 */
export interface Gmap {
    [x: string]: any;
    Map: MapConstructor;
    LatLng: MapLatLngConstructor;
    Geocoder: MapGeocoderConstructor;
    Marker: MapMarkerConstructor;
    Size: MapSizeConstructor;
    Point: MapPointConstructor;
    GeocoderStatus: typeof google.maps.GeocoderStatus;
    MapTypeId: typeof google.maps.MapTypeId;
    event: {
        clearInstanceListeners: typeof google.maps.event.clearInstanceListeners;
    };
}
